import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>
__global__ void min_reduce_kernel(const float* __restrict__ x,
                                   float* __restrict__ out,
                                   long outer_size,
                                   long reduce_size,
                                   long inner_size) {
    long total = outer_size * inner_size;
    long stride = (long)blockDim.x * gridDim.x;
    for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total; idx += stride) {
        long outer_idx = idx / inner_size;
        long inner_idx = idx % inner_size;
        const float* base = x + outer_idx * reduce_size * inner_size + inner_idx;
        float min_val = __ldg(base);
        long r = 1;
        #pragma unroll 4
        for (; r < reduce_size; r++) {
            float v = __ldg(base + r * inner_size);
            min_val = fminf(min_val, v);
        }
        out[idx] = min_val;
    }
}
__global__ void min_reduce_kernel_vec4(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        long outer_size,
                                        long reduce_size,
                                        long inner_size,
                                        long inner_vec) {
    long total = outer_size * inner_vec;
    long stride = (long)blockDim.x * gridDim.x;
    for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total; idx += stride) {
        long outer_idx = idx / inner_vec;
        long group_idx = idx % inner_vec;
        long col0 = group_idx * 4;
        const float* base = x + outer_idx * reduce_size * inner_size + col0;
        float4 min_val = *reinterpret_cast<const float4*>(base);
        #pragma unroll 4
        for (long r = 1; r < reduce_size; r++) {
            float4 v = *reinterpret_cast<const float4*>(base + r * inner_size);
            min_val.x = fminf(min_val.x, v.x);
            min_val.y = fminf(min_val.y, v.y);
            min_val.z = fminf(min_val.z, v.z);
            min_val.w = fminf(min_val.w, v.w);
        }
        float* out_base = out + outer_idx * inner_size + col0;
        *reinterpret_cast<float4*>(out_base) = min_val;
    }
}
__global__ void min_reduce_kernel_tail(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        long outer_size,
                                        long reduce_size,
                                        long inner_size,
                                        long inner_vec,
                                        long remainder) {
    long total = outer_size * remainder;
    long stride = (long)blockDim.x * gridDim.x;
    for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total; idx += stride) {
        long outer_idx = idx / remainder;
        long rem_idx = idx % remainder;
        long inner_idx = inner_vec * 4 + rem_idx;
        const float* base = x + outer_idx * reduce_size * inner_size + inner_idx;
        float min_val = __ldg(base);
        #pragma unroll 4
        for (long r = 1; r < reduce_size; r++) {
            float v = __ldg(base + r * inner_size);
            min_val = fminf(min_val, v);
        }
        out[outer_idx * inner_size + inner_idx] = min_val;
    }
}
torch::Tensor min_reduce_cuda(torch::Tensor x, int dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    x = x.contiguous();
    int ndim = x.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    auto sizes = x.sizes();
    long outer_size = 1;
    for (int i = 0; i < dim; i++) {
        outer_size *= sizes[i];
    }
    long reduce_size = sizes[dim];
    long inner_size = 1;
    for (int i = dim + 1; i < ndim; i++) {
        inner_size *= sizes[i];
    }
    std::vector<int64_t> out_sizes;
    for (int i = 0; i < ndim; i++) {
        if (i != dim) out_sizes.push_back(sizes[i]);
    }
    auto out = torch::empty(out_sizes, x.options());
    int threads = 256;
    long max_blocks = 65535L * 32L;
    bool can_vectorize = (inner_size >= 4) && (inner_size % 4 == 0);
    if (can_vectorize) {
        long inner_vec = inner_size / 4;
        long remainder = inner_size % 4;
        long total_vec = outer_size * inner_vec;
        long blocks_vec = (total_vec + threads - 1) / threads;
        if (blocks_vec > max_blocks) blocks_vec = max_blocks;
        if (blocks_vec < 1) blocks_vec = 1;
        min_reduce_kernel_vec4<<<blocks_vec, threads>>>(
            x.data_ptr<float>(),
            out.data_ptr<float>(),
            outer_size,
            reduce_size,
            inner_size,
            inner_vec
        );
        if (remainder > 0) {
            long total_tail = outer_size * remainder;
            long blocks_tail = (total_tail + threads - 1) / threads;
            if (blocks_tail > max_blocks) blocks_tail = max_blocks;
            if (blocks_tail < 1) blocks_tail = 1;
            min_reduce_kernel_tail<<<blocks_tail, threads>>>(
                x.data_ptr<float>(),
                out.data_ptr<float>(),
                outer_size,
                reduce_size,
                inner_size,
                inner_vec,
                remainder
            );
        }
    } else {
        long total = outer_size * inner_size;
        long blocks = (total + threads - 1) / threads;
        if (blocks > max_blocks) blocks = max_blocks;
        min_reduce_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(),
            out.data_ptr<float>(),
            outer_size,
            reduce_size,
            inner_size
        );
    }
    return out;
}
"""

min_reduce_cpp_source = r"""
torch::Tensor min_reduce_cuda(torch::Tensor x, int dim);
"""

min_reduce_module = load_inline(
    name="min_reduce_module",
    cpp_sources=min_reduce_cpp_source,
    cuda_sources=min_reduce_source,
    functions=["min_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs min reduction over a specific dimension using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.min_reduce = min_reduce_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.min_reduce.min_reduce_cuda(x, self.dim)


